int data = 100;
float pi = 3.14f;

// Declaration and Assignment (holds address of any type)
void* generic_ptr = &data;

// Dereferencing requires explicit casting
int value = *(int*)generic_ptr;

// Reassignment to different type is safe
generic_ptr = &pi;

// New dereferencing via new type cast
float f_val = *(float*)generic_ptr;

// Casting is crucial for memory manipulation/math
char* buffer = (char*)generic_ptr;

// Usage example: generic function signature (e.g., qsort comparator)
int compare_items(const void* a, const void* b);

// Note: Pointer arithmetic (ptr++) is illegal on void* in standard C.
